CREATE VIEW v255745 AS SELECT ST_OVERLAPS(MULTILINESTRING(LINESTRING(POINT(1, 2), POINT(1, 3))), ST_GEOMETRYFROMTEXT('geometrycollection(polygon((1 0, 3 0, 3 1, 1 1, 1 0)))')), ST_CROSSES(ST_GEOMFROMTEXT('MULTIPOINT(2 2, 5 0,10 10,20 20)'), ST_GEOMFROMTEXT('POLYGON((0 0,0 10,10 10,10 0,0 0))')), SUBSTRING_INDEX('the king of the  the hill', ' the ', -2), SUM(x4.v254534), SUM(1), SUM(x4.v254535 - 1 + x4.v254534 - 1), SUM(DISTINCT x4.v254534) FROM v254533 AS x4 GROUP BY x4.v254535 COLLATE ucs2_roman_ci